<?php
function rf_ui_assets(){static $done=false;if($done)return;$done=true;echo '<link rel="stylesheet" href="assets/return_claims.css?v=5.9.70">';}
function rf_recent_history(){rf_ui_assets();echo '<section class="card rf-claims-history"><h3>Claims History</h3>';$items=array_values(rf_journal());usort($items,fn($a,$b)=>$b['event_id']<=>$a['event_id']);$off=max(0,(int)($_GET['claims_offset']??0));$rows=[];$links=[];foreach(array_slice($items,$off,10) as $r){$t=rf_target($r);$s=rf_state($t);$resolved=rf_claim_settled($r)||!rf_followup_pending($t,rf_physical_pending($t['o']));$rows[]=[$r['platform'].' / '.$r['order'],$resolved?'Resolved / Closed':'Follow-up Needed',$s['inspection'],$r['claims']==='Approved'?'Claim Approved':$r['claims'],($r['resolution']??'').' '.($r['payment_outcome']??(rf_claim_settled($r)?'Seller Paid / Compensated':'')),mb_substr($r['remarks'],0,160),$r['recorded_at'].' · '.$r['actor']];$links[]=rf_link($r['platform'],$r['order']);}om_table(['Platform / Order','Case Status','Inspection','Claims','Resolution / Payment Outcome','Remarks','Recorded / By'],$rows,$links);echo rs8_pagination(count($items),$off,10,$_GET,'claims_offset').'</section>';}
function rf_panel(){if(!access_page_allowed('return_followup'))return;rf_ui_assets();if(can_action('return_confirm'))rf_sync_approved_claims();$rows=rf_queue();if(isset($_GET['pending_order']))$rows=array_values(array_filter($rows,fn($r)=>(int)($r['target']['o']['id']??0)===(int)$_GET['pending_order']));echo '<section class="card rf-followup-card"><div class="page-head"><div><h3>ICO Return / Refund Follow-up</h3><p>Status tags request follow-up. Inspect only physically received items; stock posts once through Inflow.</p></div><a class="btn secondary" href="?page=return_followup&amp;case_view=history">Claims History</a></div>';if(!$rows){echo '<p>No pending return / inspection / claims tasks.</p></section>';return;}$limit=($_GET['page']??'')==='inflow'?5:10;$off=max(0,(int)($_GET['pending_offset']??0));$table=[];$links=[];foreach(array_slice($rows,$off,$limit) as $r){$t=$r['target'];$s=$r['state'];$table[]=[$t['platform'].' / '.$t['order'],$r['reported'],$s['receiving'],$s['inspection'],$s['claims']];$links[]=rf_link($t['platform'],$t['order']);}om_table(['Platform / Order','Platform Status','Physical Receiving','Inspection','Claims Status'],$table,$links);echo rs8_pagination(count($rows),$off,$limit,$_GET,'pending_offset').'</section>';}
function rf_case_history($t){
 echo '<section class="card rf-details"><details><summary>Case History</summary><p class="muted small">Original entries remain permanent. Dates in remarks describe the actual event; recorded time shows when it was encoded.</p>';
 foreach(om_query("SELECT e.*,u.name actor FROM om_events e LEFT JOIN users u ON u.id=e.user_id WHERE e.event_type='Return follow-up workflow' ORDER BY e.id DESC") as $e){
  $d=json_decode($e['details_json'],true)?:[];if(($d['key']??'')!==$t['key'])continue;
  echo '<article class="om-event"><b>'.e($d['inspection'].' · '.($d['claims']==='Approved'?'Claim Approved':$d['claims'])).'</b><p class="muted small">'.e($e['created_at'].' · '.$e['actor']).'</p><p>'.nl2br(e($d['remarks'])).'</p>';
  if(!empty($d['resolution']))echo '<p>'.e($d['resolution'].' · '.($d['payment_outcome']??'')).'</p>';
  if(!empty($d['return_decision']))echo '<p>'.e($d['return_decision']).'</p>';if(!empty($d['stock_reconciliation']))echo '<p class="alert warn">'.e($d['stock_reconciliation']).'</p>';if(!empty($d['entry_mode']))echo '<p class="muted small">'.e($d['entry_mode']).'</p>';
  if(!empty($d['attachment']))echo '<a class="btn ghost sm" href="return_followup_document.php?event='.(int)$e['id'].'" target="_blank" rel="noopener">View Attachment</a>';
  echo '<p class="muted small">No stock change.</p></article>';
 }
 echo '</details></section>';
}
function rf_receiving_details($t,$s){
 $o=$t['o'];echo '<section class="card rf-details"><details><summary>Order Items &amp; Receiving</summary><p class="muted small">Only physically received items and quantities are posted. Good Item → Sellable. Damaged / Leak and For Repackaging → Non-Sellable.</p>';
 if($o&&($scope=ri_scope($o))){$rows=[];foreach($scope['totals'] as $pid=>$qty){$p=om_query('SELECT master_sku,name FROM products WHERE id=?',[$pid])->fetch();$balance=order_return_balance($t['platform'],$t['order'],$pid);$rows[]=[$p['master_sku'].' · '.$p['name'],$qty,$balance['returned'],($s['receiving']==='No Physical Return'||rf_claim_settled($s['saved']))?0:max(0,$qty-$balance['returned'])];}echo '<h4>Tagged Return Items / Quantities</h4>';om_table(['Product / SKU','Tagged Qty','Received Qty','Still Expected'],$rows);if($s['receiving']==='No Physical Return'||rf_claim_settled($s['saved']))echo '<p class="muted small">Original platform tags are retained for reference. No physical return is expected under the confirmed resolution.</p>';}
 elseif($o)echo '<p class="muted small">No verified item-level return scope is available. Select only the actual returned SKU and quantity in Inflow.</p>';
 $rows=[];$links=[];foreach($t['receipts'] as $r){$dest=[];if((int)$r['good_qty'])$dest[]='Sellable +'.$r['good_qty'].' · '.$r['platform'];if((int)$r['damaged_qty'])$dest[]='Non-Sellable / Damaged +'.$r['damaged_qty'];if((int)$r['repackaging_qty'])$dest[]='Non-Sellable / Repackaging +'.$r['repackaging_qty'];$rows[]=[$r['master_sku'].' · '.$r['name'],$r['qty'],implode('; ',$dest),$r['batch_ref']];$links[]='<a href="?page=order_return&id='.$r['batch_id'].'">Receipt / Verification</a>';}
 foreach($t['legacy'] as $r){$rows[]=[$r['master_sku'].' · '.$r['name'],$r['qty'],$r['condition'].' · '.$r['destination'],'Legacy receipt #'.$r['id']];$links[]='<a href="?page=product_detail&id='.$r['product_id'].'">Stock Movements</a>';}
 echo '<h4>Actual Received Items / Stock Effects</h4>';om_table(['Product / SKU','Received Qty','Posted Destination','Receipt'],$rows,$links);
 if(!$rows)echo '<p class="muted small">No actual return stock has been posted.</p>';
 foreach($t['wrong'] as $c)echo '<p><a class="btn ghost sm" href="?page=wrong_returns&id='.$c['id'].'">Wrong Item Case</a> '.e($c['actual_description']).' · '.(int)$c['received_qty'].' held for investigation. Expected SKU not credited.</p>';
 echo '<div class="modal-actions">';if($o)echo '<a class="btn ghost" href="?page=order_monitor&order_id='.$o['id'].'">Order / Tracking / History</a>';echo '<a class="btn ghost" href="?page=wrong_returns&view=new">Record Wrong Item Received</a></div></details></section>';
}
function rf_page(){
 rf_require();rf_ui_assets();echo '<div class="page-head"><div><a class="back" href="?page=inflow&entry=manual">← Inflow</a><h1>Return / Refund Cases</h1><p>Review the case, choose the outcome and save the details.</p></div></div>';
 if(empty($_GET['order'])){echo '<section class="card rf-lookup-card"><div class="rf-lookup-heading"><div><h3>Find Order / Return</h3><p class="muted small">Select the platform and enter an Order ID to view its return case.</p></div><a class="btn ghost sm" href="?page=return_operations_audit">Check Existing Returns</a></div><form method="get" class="rf-lookup-form"><input type="hidden" name="page" value="return_followup"><label>Platform<select name="platform">';foreach(om_shops() as $pl=>$shop)echo '<option>'.e($pl).'</option>';echo '</select></label><label>Order ID<input name="order" maxlength="100" placeholder="Enter Order ID" required></label><button type="submit" class="btn primary">Open Case</button></form></section>';if(($_GET['case_view']??'')==='history'){rf_recent_history();}else{rf_panel();echo '<div class="modal-actions"><a class="btn secondary" href="?page=return_followup&amp;case_view=history">Claims History · Resolved / Closed</a></div>';}return;}
 $t=rf_target($_GET);$s=rf_state($t);$o=$t['o'];$paid=($s['saved']['resolution']??'')==='No Physical Return Required';$physicalPending=rf_physical_pending($o);$pending=rf_followup_pending($t,$physicalPending);
 echo '<section class="card rf-summary"><div class="card-head"><div><span class="muted small">'.e($t['platform']).'</span><h2>'.e($t['order']).'</h2></div>'.'<span class="rf-case-status '.($pending?'rf-pending':'rf-resolved').'">'.($pending?'Follow-up Needed':'Resolved').'</span>'.'</div><div class="rf-summary-grid">';
 foreach(['Platform Status'=>$o?oa_reported($o)['status']:'No Original Order Record','Physical Receiving'=>$s['receiving'],'Inspection'=>$s['inspection'],'Claims'=>$s['claims']==='Approved'?'Claim Approved':$s['claims']] as $label=>$value)echo '<div><span>'.e($label).'</span><strong>'.e($value).'</strong></div>';
 echo '</div>';if(!empty($s['saved']['return_decision']))echo '<p class="rf-resolved-note">'.e($s['saved']['return_decision']).'</p>';if(!empty($s['saved']['stock_reconciliation']))echo '<p class="alert warn">'.e($s['saved']['stock_reconciliation']).'</p>';if($paid)echo '<p class="rf-resolved-note">No Physical Return Required · Seller Paid / Compensated. Dispatched stock remains deducted.</p>';echo '</section>';
 if(can_action('return_confirm')){
  echo '<section class="card"><div class="card-head"><div><h3>Update Case</h3><p class="muted small">Choose outcome → Add details → Save</p></div></div><form method="post" action="actions.php" enctype="multipart/form-data" class="stack rf-case-form" data-return-claim-form data-no-return-confirmed="'.($paid?'1':'0').'" data-confirm="Save this case update? No stock will be added or deducted.">';
  workflow_hidden('receiving_followup_save',['platform'=>$t['platform'],'order'=>$t['order'],'revision'=>$s['event_id'],'return'=>'return_followup&platform='.rawurlencode($t['platform']).'&order='.rawurlencode($t['order'])]);
  echo '<label><span class="rf-field-title">1. Case Outcome</span><select name="case_action" required>';foreach(rf_case_actions() as $value=>$label){if(!rf_case_action_visible($value,$t,$s))continue;echo '<option value="'.e($value).'">'.e($label).'</option>';}echo '</select></label><p class="rf-action-help" data-case-help>Select the next action or update the remarks / attachment.</p>';
  echo '<label class="ack" data-return-complete-ack hidden><input type="checkbox" name="return_complete_ack" value="1"> These posted received items complete the customer return. No further return is expected.</label><label class="ack" data-short-shipment-ack hidden><input type="checkbox" name="short_shipment_ack" value="1"> These posted items complete the return. The team short-shipped the order; missing units never reached the customer and require separate stock reconciliation.</label><label class="ack" data-no-return-ack hidden><input type="checkbox" name="no_return_paid_ack" value="1"> Confirmed: no physical return is expected and the seller is paid / compensated.</label><label class="ack" data-physical-inspection-ack hidden><input type="checkbox" name="physical_ack" value="1"> I confirm the item is physically received for inspection. Stock receiving is recorded separately.</label>';
  echo '<div class="rf-entry-grid"><label><span class="rf-field-title">2. Remarks</span><textarea name="remarks" rows="3" minlength="3" maxlength="4000" placeholder="Describe the result. Include actual filing / approval dates when encoding a past event." required>'.e($s['remarks']).'</textarea></label><label><span class="rf-field-title">Attachment <span class="muted small">Optional</span></span><input type="file" name="attachment" accept=".pdf,.png,.jpg,.jpeg"><span class="muted small">Platform result, claim evidence or inspection photo.</span></label></div><div class="rf-save-row"><span class="muted small">Stock changes only when actual received items are posted through Inflow.</span><button class="btn primary">3. Save Case Update</button></div></form></section>';
 }
 if($o&&$o['posting']==='Posted'&&$physicalPending&&$s['receiving']!=='No Physical Return')echo '<section class="card rf-receive-next"><div><h3>Actual item received?</h3><p class="muted small">Record only the returned SKU, quantity and inspected condition.</p></div><a class="btn secondary" href="?page=inflow&entry=manual&ur_order_id='.$o['id'].'">Receive Actual Items</a></section>';
 rf_receiving_details($t,$s);rf_case_history($t);echo '<script src="assets/return_claims.js?v=5.9.70" defer></script>';
}
